await (async()=>{const sl=ms=>new Promise(r=>setTimeout(r,ms));for(let i=0;i<24&&![...document.querySelectorAll('li')].some(l=>/Nonstop/.test(l.innerText));i++)await sl(500);await sl(800);
const b=[...document.querySelectorAll('button')].find(x=>/more flights/i.test(x.innerText));if(b){b.click();await sl(2500);}
const rows=[...document.querySelectorAll('li')].map(l=>l.innerText.split(/\n+/).map(s=>s.trim()).filter(Boolean)).filter(a=>a.includes('Nonstop')&&a.some(s=>/^\$[\d,]+$/.test(s)));
const m={};for(const a of rows){const ap=a.find(s=>/^[A-Z]{3}–[A-Z]{3}$/.test(s));if(!ap)continue;const al=a[a.indexOf(ap)-2];const p=+a.find(s=>/^\$[\d,]+$/.test(s)).slice(1).replace(',','');const bi=a.indexOf(a.find(s=>/emissions/.test(s)));const bags=a.slice(bi+1,bi+3).join('/');const k=al+'@'+ap;if(!(k in m)||p<m[k][0])m[k]=[p,bags];}
const d=[...document.querySelectorAll('input')].map(i=>i.value).filter(v=>/^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), /.test(v))[0];
return document.title.split(' |')[0]+' | '+d+' | ow='+/One way/.test(document.body.innerText)+' n='+rows.length+' '+Object.entries(m).filter(([k])=>/JetBlue|United/.test(k)).map(([k,v])=>k+'='+v[0]+'('+v[1]+')').join(' ');})()

